const SETTINGS = $('Configure Appointment Settings').first().json;

const input = $input.first().json;
const text = input.message?.text?.trim() || '';
const zone = SETTINGS.timezone || 'Asia/Kolkata';
const chatId = input.message?.chat?.id;

function invalid(message) {
  return [{ json: { valid: false, message, chatId } }];
}

const m = text.match(/^(?:book)\s+(\d{4}-\d{2}-\d{2})\s+(\d{2}:\d{2})\s+(.+?)\s+(\+?[\d\s-]{7,20})$/i);
if (!m) {
  return invalid('❌ *Invalid booking format*\n\nUse:\n`book YYYY-MM-DD HH:MM Full Name MobileNo`');
}

const [, date, time, rawName, rawMobile] = m;
const name = rawName.replace(/\s+/g, ' ').trim();
const mobile = rawMobile.replace(/[^\d+]/g, '').trim();
const digitCount = mobile.replace(/\D/g, '').length;

if (name.length < 2) {
  return invalid('❌ Please enter the customer full name.');
}
if (digitCount < 7 || digitCount > 15) {
  return invalid('❌ Please enter a valid mobile/contact number.');
}

const start = DateTime.fromFormat(`${date} ${time}`, 'yyyy-MM-dd HH:mm', { zone });
if (!start.isValid) {
  return invalid('❌ Invalid date or time. Use `YYYY-MM-DD HH:MM`.');
}

const now = DateTime.now().setZone(zone);
if (start <= now) {
  return invalid('❌ Appointment must be in the future.');
}

const weekday = start.weekday;
if (weekday === 7) {
  return invalid('🚫 *Office is closed on Sunday.*\n\nPlease choose Monday-Saturday.');
}

let openingHour;
let closingHour;
if (weekday >= 1 && weekday <= 5) {
  openingHour = Number(SETTINGS.weekdayOpen);
  closingHour = Number(SETTINGS.weekdayClose);
} else {
  openingHour = Number(SETTINGS.weekdayOpen);
  closingHour = Number(SETTINGS.saturdayClose);
}

const opening = start.startOf('day').set({ hour: openingHour, minute: 0, second: 0, millisecond: 0 });
const closing = start.startOf('day').set({ hour: closingHour, minute: 0, second: 0, millisecond: 0 });
const consultationEnd = start.plus({ minutes: Number(SETTINGS.consultationMinutes) });
const protectedBlockEnd = start.plus({ minutes: Number(SETTINGS.consultationMinutes)+Number(SETTINGS.breakMinutes) });

if (start < opening || protectedBlockEnd > closing) {
  const lastStart = closing.minus({ minutes: Number(SETTINGS.consultationMinutes)+Number(SETTINGS.breakMinutes) });
  const dayName = weekday === 6 ? 'Saturday' : 'Monday-Friday';
  return invalid(
    `⏰ *Outside office hours*\n\n${dayName}: ${opening.toFormat('HH:mm')}-${closing.toFormat('HH:mm')}\nLatest booking start: ${lastStart.toFormat('HH:mm')}`
  );
}

const bookingId = `APT-${start.toFormat('yyyyMMdd-HHmm')}-${now.toMillis().toString().slice(-6)}`;

return [{
  json: {
    valid: true,
    name,
    mobile,
    bookingId,
    summary: `Appointment | ${name} | ${mobile}`,
    startDateTime: start.toISO(),
    endDateTime: consultationEnd.toISO(),
    blockEndDateTime: protectedBlockEnd.toISO(),
    timestamp: now.toFormat('yyyy-MM-dd HH:mm:ss'),
    chatId
  }
}];

const SETTINGS = $('Configure Appointment Settings').first().json;

const zone = SETTINGS.timezone || 'Asia/Kolkata';
const p = $('Parse Booking').item.json;
const candidateStart = DateTime.fromISO(p.startDateTime).setZone(zone);
const candidateBlockEnd = DateTime.fromISO(p.blockEndDateTime).setZone(zone);

const rawEvents = $input.all().map(i => i.json).filter(e => e && e.id);

function eventRange(e) {
  if (e.start?.dateTime && e.end?.dateTime) {
    return {
      id: e.id,
      summary: e.summary || '',
      start: DateTime.fromISO(e.start.dateTime).setZone(zone),
      end: DateTime.fromISO(e.end.dateTime).setZone(zone),
    };
  }

  if (e.start?.date && e.end?.date) {
    return {
      id: e.id,
      summary: e.summary || '',
      start: DateTime.fromISO(e.start.date, { zone }).startOf('day'),
      end: DateTime.fromISO(e.end.date, { zone }).startOf('day'),
    };
  }

  return null;
}

const events = rawEvents.map(eventRange).filter(Boolean);

// Every existing calendar event gets a 10-minute protected buffer after it.
// Candidate itself reserves 60 minutes: 50-minute consultation + 10-minute break.
const conflicts = events.filter(e => {
  const existingBusyEnd = e.end.plus({ minutes: Number(SETTINGS.breakMinutes) });
  return e.start < candidateBlockEnd && existingBusyEnd > candidateStart;
});

return [{
  json: {
    slotAvailable: conflicts.length === 0,
    conflictCount: conflicts.length,
    conflictingEvents: conflicts.map(e => ({
      id: e.id,
      summary: e.summary,
      start: e.start.toISO(),
      end: e.end.toISO(),
    }))
  }
}];

