const msg = $('Telegram Trigger').first().json.message || {};
const userId = String(msg.from?.id || '');
const chatId = String(msg.chat?.id || '');
const mode = $input.first().json.guided?.mode || 'lookup';
if (!userId || !chatId || msg.chat?.type !== 'private') return [{json:{userId:'',chatId,mode,timeMin:DateTime.now().toISO(),timeMax:DateTime.now().plus({years:1}).toISO()}}];
return [{json:{userId,chatId,mode,timeMin:DateTime.now().setZone('Asia/Kolkata').toISO(),timeMax:DateTime.now().setZone('Asia/Kolkata').plus({years:1}).toISO()}}];

const q=$('Parse Appointment Lookup').first().json;
const all=$input.all().map(i=>i.json).filter(e=>e?.id && e.start?.dateTime);
const matches=all.filter(e=> {
 const d=e.description||'';
 const u=(d.match(/^Telegram User ID:\s*(\d+)/im)||[])[1];
 const c=(d.match(/^Telegram Chat ID:\s*(\d+)/im)||[])[1];
 return q.userId && (u===q.userId || (!u && c===q.chatId && q.chatId===q.userId));
}).sort((a,b)=>new Date(a.start.dateTime)-new Date(b.start.dateTime));
const db=$getWorkflowStaticData('global');db.telegramAppointmentSessions=db.telegramAppointmentSessions||{};
const key=q.chatId;
if (!matches.length){delete db.telegramAppointmentSessions[key];return [{json:{message:'📋 No upcoming appointments are linked to your Telegram account.\n\nOlder bookings without a Telegram ID need manual verification by the office.',mode:q.mode}}];}
const shown=matches.slice(0,9);
let message='📋 *Your upcoming appointments*\n\n';
shown.forEach((e,i)=>{const s=DateTime.fromISO(e.start.dateTime).setZone('Asia/Kolkata');message+=`${i+1}. ${s.toFormat('dd LLL yyyy, hh:mm a')}\n`;});
if(matches.length>9) message+='\nShowing the next 9 appointments.\n';
if(q.mode==='lookup') {delete db.telegramAppointmentSessions[key];message+='\nChoose Cancel or Reschedule from the main menu.';}
else {
 db.telegramAppointmentSessions[key]={flow:q.mode,step:'select',data:{items:shown.map(e=>({id:e.id,summary:e.summary||'',description:e.description||'',start:e.start.dateTime,end:e.end?.dateTime||''}))},updatedAt:Date.now()};
 message+=`\nReply with an appointment number (1-${shown.length}).`;
}
return [{json:{message,mode:q.mode}}];

const p = $('Parse Booking').item.json;
const zone = 'Asia/Kolkata';

const requested = DateTime.fromISO(p.startDateTime).setZone(zone);
const searchStart = requested.startOf('day');
const searchEnd = requested.plus({ days: 8 }).startOf('day');

return [{
  json: {
    requestedStart: requested.toISO(),
    searchStart: searchStart.toISO(),
    searchEnd: searchEnd.toISO()
  }
}];

const SETTINGS = $('Configure Appointment Settings').first().json;

const zone = SETTINGS.timezone || 'Asia/Kolkata';
const p = $('Parse Booking').item.json;
const requested = DateTime.fromISO(p.startDateTime).setZone(zone);
const now = DateTime.now().setZone(zone);

const rawEvents = $input.all()
  .map(i => i.json)
  .filter(e => e && e.id);

function eventRange(e) {
  if (e.start?.dateTime && e.end?.dateTime) {
    return {
      start: DateTime.fromISO(e.start.dateTime).setZone(zone),
      end: DateTime.fromISO(e.end.dateTime).setZone(zone),
    };
  }

  if (e.start?.date && e.end?.date) {
    return {
      start: DateTime.fromISO(e.start.date, { zone }).startOf('day'),
      end: DateTime.fromISO(e.end.date, { zone }).startOf('day'),
    };
  }

  return null;
}

const events = rawEvents.map(eventRange).filter(Boolean);

function officeWindow(day) {
  if (day.weekday === 7) return null;

  const openingHour = Number(SETTINGS.weekdayOpen);
  const closingHour = day.weekday === 6 ? Number(SETTINGS.saturdayClose) : Number(SETTINGS.weekdayClose);

  return {
    open: day.startOf('day').set({ hour: openingHour, minute: 0, second: 0, millisecond: 0 }),
    close: day.startOf('day').set({ hour: closingHour, minute: 0, second: 0, millisecond: 0 }),
  };
}

function isFree(start) {
  const window = officeWindow(start);
  if (!window) return false;

  const blockEnd = start.plus({ minutes: Number(SETTINGS.consultationMinutes)+Number(SETTINGS.breakMinutes) });
  if (start < window.open || blockEnd > window.close) return false;
  if (start <= now) return false;

  return !events.some(e => {
    const existingBusyEnd = e.end.plus({ minutes: Number(SETTINGS.breakMinutes) });
    return e.start < blockEnd && existingBusyEnd > start;
  });
}

const sameDate = [];
const requestedWindow = officeWindow(requested);

if (requestedWindow) {
  for (
    let candidate = requestedWindow.open;
    candidate.plus({ minutes: Number(SETTINGS.consultationMinutes)+Number(SETTINGS.breakMinutes) }) <= requestedWindow.close;
    candidate = candidate.plus({ minutes: 15 })
  ) {
    if (candidate.toMillis() === requested.toMillis()) continue;
    if (isFree(candidate)) sameDate.push(candidate);
  }
}

const sameTimeOtherDates = [];
for (let d = 1; d <= 7; d++) {
  const candidate = requested.plus({ days: d });
  if (isFree(candidate)) sameTimeOtherDates.push(candidate);
}

let message =
  `❌ *Requested slot is occupied*\n\n` +
  `👤 ${p.name}\n` +
  `📱 ${p.mobile}\n` +
  `📅 ${requested.toFormat('dd LLL yyyy')}\n` +
  `🕒 ${requested.toFormat('hh:mm a')} - ${requested.plus({ minutes: Number(SETTINGS.consultationMinutes) }).toFormat('hh:mm a')}\n` +
  `☕ Protected break until ${requested.plus({ minutes: Number(SETTINGS.consultationMinutes)+Number(SETTINGS.breakMinutes) }).toFormat('hh:mm a')}\n\n`;

if (sameDate.length) {
  message += `✅ *Available slots on the same date:*\n`;
  for (const s of sameDate.slice(0, 6)) {
    message += `• ${s.toFormat('hh:mm a')} - ${s.plus({ minutes: Number(SETTINGS.consultationMinutes) }).toFormat('hh:mm a')}\n`;
  }
  message += `\n`;
} else {
  message += `ℹ️ No other valid slots are available on the same date.\n\n`;
}

if (sameTimeOtherDates.length) {
  message += `📆 *Same time on other dates:*\n`;
  for (const s of sameTimeOtherDates.slice(0, 5)) {
    message += `• ${s.toFormat('dd LLL yyyy')} — ${s.toFormat('hh:mm a')} - ${s.plus({ minutes: Number(SETTINGS.consultationMinutes) }).toFormat('hh:mm a')}\n`;
  }
  message += `\n`;
} else {
  message += `ℹ️ The same time is not available during the next 7 days.\n\n`;
}

message +=
  `To book one of these slots, send:\n` +
  `\`book YYYY-MM-DD HH:MM ${p.name} ${p.mobile}\`\n\n` +
  `*This message was sent automatically From Dr. X Office*`;

return [{ json: { message } }];

const input = $input.first().json;
const msg = input.message || {};
const chatId = msg.chat?.id;
const originalText = (msg.text || '').trim();
const text = originalText;
const lower = text.toLowerCase();
const zone = 'Asia/Kolkata';

if (!chatId) {
  return [{ json: { ...input, guided: { action: 'pass' } } }];
}

const data = $getWorkflowStaticData('global');
data.telegramAppointmentSessions = data.telegramAppointmentSessions || {};
const sessions = data.telegramAppointmentSessions;
const key = String(chatId);
const userId=String(msg.from?.id || '');
const now = DateTime.now().setZone(zone);

let session = sessions[key] || null;
if (session?.updatedAt && (now.toMillis() - session.updatedAt) > 30 * 60 * 1000) {
  delete sessions[key];
  session = null;
}

function save(s) {
  s.updatedAt = now.toMillis();
  sessions[key] = s;
  session = s;
}

function clear() {
  delete sessions[key];
  session = null;
}

function result(action, prompt = '', command = null) {
  const nextMessage = { ...msg };
  if (command !== null) nextMessage.text = command;
  return [{
    json: {
      ...input,
      message: nextMessage,
      guided: { action, prompt, mode:session?.flow || 'lookup' }
    }
  }];
}

function cleanMobile(value) {
  const cleaned = String(value || '').replace(/[^\d+]/g, '').trim();
  const digits = cleaned.replace(/\D/g, '');
  return { cleaned, valid: digits.length >= 7 && digits.length <= 15 };
}

function startFlow(flow) {
  const s = { flow, step: 'name', data: {} };
  save(s);
  if (flow === 'book') {
    return result('prompt', '📅 *Book Appointment*\n\nPlease enter the patient *full name*.');
  }
  if (flow === 'cancel') {
    return result('pass', '', 'appointments');
  }
  return result('pass', '', 'appointments');
}

// Global navigation
if (['/start', 'start', 'hi', 'hello', 'hey', '🏠 main menu', 'main menu', '/menu'].includes(lower)) {
  clear();
  return result('menu');
}

if (text === '📅 Book Appointment') return startFlow('book');
if (text === '📋 My Appointments') { clear(); return result('pass','','appointments'); }
if (text === '❌ Cancel Appointment') { clear(); save({flow:'cancel',step:'loading',data:{}}); return result('pass','','appointments'); }
if (text === '🔄 Reschedule Appointment') {clear();save({flow:'reschedule',step:'loading',data:{}});return result('pass','','appointments');}

if (text === '↩️ Start Over') {
  if (session?.flow) return startFlow(session.flow);
  clear();
  return result('menu');
}


// Select a verified appointment from the list generated from this Telegram identity.
if(session?.step==='select') {
 const ix=Number(text);
 if(!/^\d+$/.test(text)||ix<1||ix>session.data.items.length) return result('prompt',`Select a number from 1-${session.data.items.length}, or Main Menu.`);
 const e=session.data.items[ix-1];
 session.data.selected=e;
 if(session.flow==='cancel'){
   session.step='confirm_cancel_id';save(session);
   const start=DateTime.fromISO(e.start).setZone(zone);
   return result('confirm_cancel',`❌ *Confirm cancellation*\n\n📅 ${start.toFormat('dd LLL yyyy')}\n🕒 ${start.toFormat('hh:mm a')}\n\nCancel this appointment?`);
 }
 session.step='reschedule_date';save(session);
 return result('prompt','🔄 *Reschedule*\n\nEnter the new date: `YYYY-MM-DD`');
}
if(session?.step==='confirm_cancel_id') {
 if(text==='✅ Confirm Cancellation') {const eventId=session.data.selected.id;clear();return result('pass','',`cancel_id ${eventId}`);}
 return result('confirm_cancel','Confirm cancellation, or use Main Menu.');
}
if(session?.step==='reschedule_date') {
 const dt=DateTime.fromFormat(text,'yyyy-MM-dd',{zone});
 if(!/^\d{4}-\d{2}-\d{2}$/.test(text)||!dt.isValid||dt.toFormat('yyyy-MM-dd')!==text) return result('prompt','Enter a valid date: `YYYY-MM-DD`');
 session.data.date=text;session.step='reschedule_time';save(session);
 return result('prompt','Enter the new start time: `HH:MM` (24-hour format).');
}
if(session?.step==='reschedule_time') {
 const dt=DateTime.fromFormat(text,'HH:mm',{zone});
 if(!/^\d{2}:\d{2}$/.test(text)||!dt.isValid||dt.toFormat('HH:mm')!==text) return result('prompt','Enter a valid time: `HH:MM`.');
 session.data.time=text;session.step='confirm_reschedule';save(session);
 return result('confirm_reschedule',`🔄 *Confirm reschedule*\n\nNew appointment: ${session.data.date}, ${text}\n\nConfirm this change?`);
}
if(session?.step==='confirm_reschedule') {
 if(text==='✅ Confirm Reschedule') {const {selected,date,time}=session.data;clear();return result('pass','',`reschedule_id ${selected.id} ${date} ${time}`);}
 return result('confirm_reschedule','Confirm rescheduling, or choose Main Menu.');
}

// No guided session: preserve the original command interface.
if (!session) return result('pass');

session.updatedAt = now.toMillis();

// STEP 1: Full name
if (session.step === 'name') {
  const name = text.replace(/\s+/g, ' ').trim();
  if (name.length < 2 || name.startsWith('📅') || name.startsWith('📋') || name.startsWith('❌')) {
    save(session);
    return result('prompt', '⚠️ Please enter the patient *full name*.\n\nExample: `Harpreet Singh`');
  }
  session.data.name = name;
  session.step = 'mobile';
  save(session);
  return result('prompt', `👤 *${name}*\n\nPlease enter the *mobile/contact number*.\n\nExample: \`9876543210\``);
}

// STEP 2: Mobile number. Also accepts Telegram contact messages.
if (session.step === 'mobile') {
  const rawMobile = msg.contact?.phone_number || text;
  const mobile = cleanMobile(rawMobile);
  if (!mobile.valid) {
    save(session);
    return result('prompt', '⚠️ Please enter a valid mobile/contact number.\n\nUse 7-15 digits.');
  }
  session.data.mobile = mobile.cleaned;

  if (session.flow === 'lookup') {
    const command = `appointments ${session.data.name} ${session.data.mobile}`;
    clear();
    return result('pass', '', command);
  }

  session.step = 'date';
  save(session);
  return result('prompt', `📅 Enter the appointment *date*.\n\nFormat: \`YYYY-MM-DD\`\nExample: \`${now.plus({days:1}).toFormat('yyyy-MM-dd')}\``);
}

// STEP 3: Date
if (session.step === 'date') {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    save(session);
    return result('prompt', '⚠️ Invalid date format.\n\nPlease use: `YYYY-MM-DD`');
  }
  const parsedDate = DateTime.fromFormat(text, 'yyyy-MM-dd', { zone });
  if (!parsedDate.isValid || parsedDate.toFormat('yyyy-MM-dd') !== text) {
    save(session);
    return result('prompt', '⚠️ Invalid date.\n\nPlease enter a real date using `YYYY-MM-DD`.');
  }
  session.data.date = text;
  session.step = 'time';
  save(session);
  return result('prompt', '🕒 Enter the preferred *start time*.\n\n24-hour format: `HH:MM`\nExample: `10:00`');
}

// STEP 4: Time
if (session.step === 'time') {
  if (!/^\d{2}:\d{2}$/.test(text)) {
    save(session);
    return result('prompt', '⚠️ Invalid time format.\n\nPlease use 24-hour `HH:MM`.');
  }
  const parsedTime = DateTime.fromFormat(text, 'HH:mm', { zone });
  if (!parsedTime.isValid || parsedTime.toFormat('HH:mm') !== text) {
    save(session);
    return result('prompt', '⚠️ Invalid time.\n\nExample: `10:00` or `14:30`');
  }
  session.data.time = text;
  session.step = 'confirm';
  save(session);

